sql.where:
t.deleted = 0

    AND t.task_no LIKE CONCAT('%', #{req.taskNo}, '%')


    AND t.rule_id = #{req.ruleId}


    AND t.qc_plan_id = #{req.qcPlanId}


    AND t.trigger_point = #{req.triggerPoint}


    AND t.biz_type = #{req.bizType}


    AND t.biz_no LIKE CONCAT('%', #{req.bizNo}, '%')


    AND t.mat_id = #{req.matId}


    AND t.mat_code LIKE CONCAT('%', #{req.matCode}, '%')


    AND t.mat_name LIKE CONCAT('%', #{req.matName}, '%')


    AND t.lot_no LIKE CONCAT('%', #{req.lotNo}, '%')


    AND t.assigned_inspector_id = #{req.assignedInspectorId}


    AND t.conclusion = #{req.conclusion}


    AND t.status = #{req.status}


    AND t.inspect_start_time BETWEEN #{req.inspectStartTime[0]} AND #{req.inspectStartTime[1]}


    AND t.create_time BETWEEN #{req.createTime[0]} AND #{req.createTime[1]}
